import sys


def price(quantity):
    if quantity < 0:
        raise ValueError("quantity must be non-negative")
    return quantity * 10 + 1


if __name__ == '__main__':
    try:
        print(price(int(sys.argv[1])))
    except ValueError as exc:
        sys.exit(str(exc))

